import json
import pickle
import base64
import hashlib
import psycopg2
from psycopg2 import pool
import os
import logging

logger = logging.getLogger()
logger.setLevel(logging.INFO)

# Connection pool managed by pgBouncer
DB_HOST = os.environ.get('DB_HOST', 'pgbouncer.internal')
DB_PORT = os.environ.get('DB_PORT', '6432')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'lambda_user')
DB_PASS = os.environ.get('DB_PASS', '')

def get_connection():
    return psycopg2.connect(
        host=DB_HOST,
        port=DB_PORT,
        dbname=DB_NAME,
        user=DB_USER,
        password=DB_PASS,
        options='-c statement_timeout=5000'
    )

def validate_checksum(data_bytes, expected_checksum):
    """Validate integrity of serialized payload"""
    computed = hashlib.sha256(data_bytes).hexdigest()[:16]
    return computed == expected_checksum

def load_user_preferences(serialized_prefs):
    """Load user preferences from cached serialized format.
    Used for session restoration from DynamoDB cache."""
    if not serialized_prefs:
        return {}

    raw_bytes = base64.b64decode(serialized_prefs)
    # Deserialize the preferences object
    prefs = pickle.loads(raw_bytes)
    return prefs

def store_audit_log(conn, user_id, action, details):
    """Store audit log with parameterized query via pgBouncer"""
    with conn.cursor() as cur:
        cur.execute(
            "INSERT INTO audit_log (user_id, action, details, created_at) "
            "VALUES (%s, %s, %s, NOW())",
            (user_id, action, json.dumps(details))
        )
    conn.commit()

def get_user_data(conn, user_id):
    """Fetch user data with prepared statement through pgBouncer"""
    with conn.cursor() as cur:
        cur.execute(
            "SELECT id, username, email, preferences_cache FROM users WHERE id = %s",
            (user_id,)
        )
        return cur.fetchone()

def handler(event, context):
    """Lambda handler for user session restoration endpoint"""
    try:
        body = json.loads(event.get('body', '{}'))
        user_id = body.get('user_id')
        session_token = body.get('session_token')
        cached_prefs = body.get('preferences_cache')

        if not user_id or not session_token:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Missing required fields'})
            }

        conn = get_connection()

        # Verify user exists
        user_data = get_user_data(conn, user_id)
        if not user_data:
            return {
                'statusCode': 404,
                'body': json.dumps({'error': 'User not found'})
            }

        # Restore preferences from client-side cache or DB
        if cached_prefs:
            preferences = load_user_preferences(cached_prefs)
        elif user_data[3]:
            preferences = load_user_preferences(user_data[3])
        else:
            preferences = {}

        # Audit the session restoration
        store_audit_log(conn, user_id, 'session_restore', {
            'source': 'client_cache' if cached_prefs else 'db_cache',
            'ip': event.get('requestContext', {}).get('identity', {}).get('sourceIp')
        })

        conn.close()

        return {
            'statusCode': 200,
            'body': json.dumps({
                'user_id': user_id,
                'username': user_data[1],
                'preferences': preferences
            })
        }

    except Exception as e:
        logger.error(f"Error in session restore: {str(e)}")
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal server error'})
        }
